// werkt zou moeten kennen. Niveau: basis tot gevorderd. Stand van zaken: oktober 2026.
// Schrijfregels: het juiste antwoord is niet opvallend het langste, afleiders zijn echte
// begrippen of veelgemaakte denkfouten, en de vraag verraadt het antwoord niet via woordkeuze.

export const TOPICS = {
  klimaat: 'Klimaat en CO₂',
  regels: 'Wet- en regelgeving',
  circulair: 'Circulaire economie',
  meten: 'Strategie en meten',
  natuur: 'Natuur en biodiversiteit',
  sociaal: 'Mensen en keten',
  claims: 'Communicatie en claims',
  energie: 'Energietransitie'
};

const C = (id, topic, prompt, answer, distractors, explanation) => ({id, topic, kind: 'choice', prompt, answer, aliases: [answer], distractors, explanation});
const T = (id, topic, prompt, answer, aliases, explanation) => ({id, topic, kind: 'input', prompt, answer, aliases: [answer, ...aliases], distractors: [], explanation});
const A = (label, aliases = [], explanation = '') => ({label, aliases: [label, ...aliases], explanation});
const D = (id, topic, subject, explanation, answers) => ({id, topic, prompt: `Waar denk je aan bij ${subject}?`, goal: 5, explanation, answers: answers.map((a, i) => ({...a, id: id + '-a' + i}))});
const P = (id, topic, prompt, groups, decoys, explanation) => ({id, topic, prompt, groupSize: 4, decoys, explanation, groups: groups.map(([label, cards, why], i) => ({id: id + '-g' + i, label, cards, explanation: why}))});
const K = (id, topic, label, definition, explanation, conflictIds = []) => ({id, topic, label, definition, explanation, conflictIds});
const F = (id, topic, prompt, answers, explanation) => ({id, topic, prompt, goal: Math.min(5, answers.length), explanation, answers: answers.map((a, i) => ({...a, id: id + '-a' + i}))});

